# Break My Fix finding 1, generated by Tracefix: Env.db_url returns a wrong value.
# Property (issue): env.db_url with extra_options returns a config whose OPTIONS contain the extra_options entries.
# Quote: Perhaps they can be passed in a new `extra_options` argument?
# Run it with pytest: it fails for as long as the code breaks this property.

from environ.environ import Env


def test_break_my_fix_1() -> None:
    self_after = Env()
    var = 'DJANGO_ENVIRON_SURELY_UNSET_VAR'
    default = 'sqlite://:memory:'
    extra_options = {'timeout': 20}
    # The property applies to this input: var == 'DJANGO_ENVIRON_SURELY_UNSET_VAR' and isinstance(default, str) and default.split('://')[0] in Env.DB_SCHEMES and isinstance(extra_options, dict) and len(extra_options) > 0
    result = self_after.db_url(var=var, default=default, extra_options={'timeout': 20})
    assert (isinstance(result.get('OPTIONS'), dict) and all(k in result['OPTIONS'] and result['OPTIONS'][k] == v for k, v in extra_options.items()))
